add_action( 'wp', function () {
	if ( ! current_user_can( 'manage_options' ) ) {
		show_admin_bar( false );
	}
} );

add_action( 'rest_api_init', function () {
	register_rest_route( 'pbc/v1', '/wa', array(
		'methods'             => 'POST',
		'permission_callback' => '__return_true',
		'callback'            => function ( $req ) {
			$src = sanitize_key( (string) $req->get_param( 's' ) );
			if ( '' === $src ) { $src = 'lain'; }
			$ip  = isset( $_SERVER['REMOTE_ADDR'] ) ? $_SERVER['REMOTE_ADDR'] : '';
			$key = 'pbc_wa_' . md5( $ip . $src );
			if ( get_transient( $key ) ) { return array( 'ok' => true, 'dup' => true ); }
			set_transient( $key, 1, 30 );
			$day = current_time( 'Y-m-d' );
			$all = get_option( 'pbc_wa_clicks', array() );
			if ( ! is_array( $all ) ) { $all = array(); }
			if ( ! isset( $all[ $day ] ) ) { $all[ $day ] = array(); }
			$all[ $day ][ $src ] = ( isset( $all[ $day ][ $src ] ) ? $all[ $day ][ $src ] : 0 ) + 1;
			if ( count( $all ) > 180 ) { ksort( $all ); $all = array_slice( $all, -180, null, true ); }
			update_option( 'pbc_wa_clicks', $all, false );
			return array( 'ok' => true );
		},
	) );
	register_rest_route( 'pbc/v1', '/wa-stats', array(
		'methods'             => 'GET',
		'permission_callback' => '__return_true',
		'callback'            => function () { return get_option( 'pbc_wa_clicks', array() ); },
	) );
	register_rest_route( 'pbc/v1', '/wa-reset', array(
		'methods'             => 'POST',
		'permission_callback' => function () { return current_user_can( 'manage_options' ); },
		'callback'            => function () { update_option( 'pbc_wa_clicks', array(), false ); return array( 'ok' => true ); },
	) );
} );

