// Hapus skema Article/Person bawaan Rank Math di halaman utama (bukan artikel)
add_filter( 'rank_math/json_ld', function ( $data ) {
	if ( is_page( array( 344, 415, 23, 427, 438, 439, 469, 470, 473, 474, 535, 536 ) ) || is_front_page() ) {
		foreach ( $data as $k => $v ) {
			if ( is_array( $v ) && isset( $v['@type'] ) && in_array( $v['@type'], array( 'Article', 'BlogPosting', 'Person' ), true ) ) { unset( $data[ $k ] ); }
		}
	}
	return $data;
}, 99 );

// Link pendek untuk bio Instagram: pratamabuild.id/demo dan pratamabuild.id/sistem
add_action( 'template_redirect', function () {
	$path = trim( (string) parse_url( $_SERVER['REQUEST_URI'], PHP_URL_PATH ), '/' );
	$map  = array(
		'demo'   => 'https://sistem.pratamabuild.id/?demo=1',
		'sistem' => 'https://sistem.pratamabuild.id/',
		'media'  => 'PAGE',
	);
	// Halaman lama (situs versi awal) dialihkan permanen ke halaman baru
	$old = array(
		'beranda' => '/', 'beranda-2' => '/',
		'tentang-kami' => '/about/',
		'layanan' => '/#layanan', 'layanan-2' => '/#layanan',
		'portofolio' => '/#hasil-kerja', 'portofolio-2' => '/#hasil-kerja',
		'alasan-memilih-kami' => '/#kenapa-pbc', 'alasan-memilih-kami-2' => '/#kenapa-pbc',
		'testimoni' => '/#ulasan', 'testimoni-2' => '/#ulasan',
		'kontak' => '/#konsultasi', 'kontak-2' => '/#konsultasi',
		'abraham' => '/links/', 'hello-world' => '/', 'sample-page' => '/', 'proyek' => '/#hasil-kerja', 'galeri' => '/#hasil-kerja', 'blog' => '/',
	);
	if ( isset( $old[ $path ] ) ) {
		wp_redirect( home_url( $old[ $path ] ), 301 );
		exit;
	}
	if ( isset( $map[ $path ] ) ) {
		$c = get_option( 'pbc_short_clicks', array() );
		$d = wp_date( 'Y-m-d' );
		$c[ $d ][ $path ] = isset( $c[ $d ][ $path ] ) ? $c[ $d ][ $path ] + 1 : 1;
		update_option( 'pbc_short_clicks', $c, false );
		nocache_headers();
		if ( 'PAGE' === $map[ $path ] ) {
			do_action( 'litespeed_control_set_nocache', 'pbc media counter' );
			status_header( 200 );
			header( 'Content-Type: text/html; charset=utf-8' );
			echo pbc_media_page();
			exit;
		}
		wp_redirect( $map[ $path ], 302 );
		exit;
	}
}, 1 );

